import crypto from 'crypto';
import type { EngineConfiguration, EngineResourceMapping } from '../../../../domain/ports/infrastructure-engine.port.js';

/**
 * Pure OpenTofu configuration for one Azure environment (testing profile:
 * everything scales to zero except the database). Values are non-secret:
 * runtime secrets live in Key Vault (written by Hypervibe, referenced by the
 * Container Apps), and the database administrator password is write-only and
 * generated by an ephemeral resource, so no secret enters configuration,
 * plan or state. See docs/opentofu-engine-azure.md.
 */
export interface AzureEngineInput {
  tenantId: string;
  subscriptionId: string;
  /** The project's resource group, created by setup; the deploy identity's roles stop at it. */
  resourceGroup: string;
  location: string;
  /** Short stable prefix for names, e.g. `hv-billforge-test`. */
  prefix: string;
  /** Environment id stamped on owned resources so adoption can prove ownership. */
  environmentId: string;
  /** Object id of the deploy identity: the database's Entra administrator. */
  deployPrincipalId: string;
  /** Display name of the deploy identity (the Entra administrator's principal name). */
  deployPrincipalName: string;
  database?: AzureDatabaseInput;
  storage?: Array<{ name: string; container: string }>;
  services?: AzureWebServiceInput[];
  /** Names of the runtime secrets in this environment's Key Vault, referenced by every service. */
  secretKeys?: string[];
}

export interface AzureDatabaseInput {
  /** PostgreSQL major version. */
  version: number;
  /** Burstable B1ms by default (testing and production profiles alike; see the design doc). */
  skuName?: string;
  storageMb?: number;
}

export interface AzureWebServiceInput {
  logicalName: string;
  /** Container App name (2-32 characters). */
  resourceName: string;
  /** Image for first creation, already in this environment's registry; the release path owns it afterwards. */
  initialImage: string;
  public: boolean;
  targetPort: number;
  /** Non-secret configuration only; secrets come from Key Vault references. */
  env?: Record<string, string>;
  healthCheckPath?: string;
  /** vCPU and GiB; Container Apps consumption pairs them (0.25/0.5, 0.5/1, ...). */
  cpu?: number;
  memory?: number;
  maxReplicas?: number;
}

export const azureKey = (name: string) => name.toLowerCase().replace(/[^a-z0-9_]/g, '_');

/** Key Vault and Container Apps secret name for an environment variable: DATABASE_URL -> database-url. */
export function azureSecretName(key: string): string {
  const name = key.toLowerCase().replace(/_/g, '-').replace(/[^a-z0-9-]/g, '').replace(/-+/g, '-').replace(/^-|-$/g, '');
  if (!/^[a-z][a-z0-9-]{0,126}$/.test(name)) throw new Error(`Secret ${key} cannot be stored in Key Vault under a valid name.`);
  return name;
}

/**
 * Globally unique names (storage account, key vault, registry, database server)
 * get a short suffix derived from the subscription and environment, so they are
 * stable across plans and never collide with another tenant's.
 */
export function azureGlobalNames(input: Pick<AzureEngineInput, 'subscriptionId' | 'environmentId' | 'prefix'>): { storage: string; vault: string; registry: string; database: string } {
  const suffix = crypto.createHash('sha256').update(`${input.subscriptionId}/${input.environmentId}`).digest('hex').slice(0, 6);
  const compact = input.prefix.replace(/[^a-z0-9]/g, '');
  return {
    storage: `${compact.slice(0, 18)}${suffix}`,
    vault: `${input.prefix.slice(0, 17).replace(/-+$/, '')}-${suffix}`,
    registry: `${compact.slice(0, 44)}${suffix}`,
    database: `${input.prefix.slice(0, 56).replace(/-+$/, '')}-${suffix}`,
  };
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ROLE = {
  acrPull: '7f951dda-4ed3-4680-a7ca-43fe172d538d',
  keyVaultSecretsUser: '4633458b-17de-408a-b874-0445c86b69e6',
  storageBlobDataContributor: 'ba92f5b4-2d11-453d-a403-e96b0029c9fe',
};

export function buildAzureConfiguration(input: AzureEngineInput): EngineConfiguration {
  for (const [field, value] of [['tenant', input.tenantId], ['subscription', input.subscriptionId], ['deploy identity', input.deployPrincipalId]] as const) {
    if (!UUID.test(value)) throw new Error(`Azure ${field} id is invalid.`);
  }
  if (!/^hv-[a-z0-9-]{1,60}$/.test(input.resourceGroup)) throw new Error('Azure resource group is invalid.');
  if (!/^[a-z][a-z0-9]{2,30}$/.test(input.location)) throw new Error('Azure location is invalid.');
  if (!/^[a-z][a-z0-9-]{2,24}[a-z0-9]$/.test(input.prefix)) throw new Error('Azure name prefix is invalid.');
  const names = azureGlobalNames(input);
  const tags = { 'managed-by': 'hypervibe', 'hv-environment': input.environmentId.toLowerCase() };
  const placed = { resource_group_name: input.resourceGroup, location: input.location, tags };
  const resources: Record<string, EngineResourceMapping> = {};
  const roleAssignment = (scope: string, role: string, description: string) => ({
    scope, role_definition_id: `/subscriptions/${input.subscriptionId}/providers/Microsoft.Authorization/roleDefinitions/${role}`,
    principal_id: '${azurerm_user_assigned_identity.runtime.principal_id}', principal_type: 'ServicePrincipal', description,
  });
  const files: Record<string, unknown> = {
    'provider.tf.json': { provider: { azurerm: [{
      subscription_id: input.subscriptionId, tenant_id: input.tenantId,
      // Setup registered the resource providers with the subscription Owner; the deploy identity cannot.
      resource_provider_registrations: 'none',
      // Storage accounts have shared keys turned off, so the provider uses Entra ID for them too.
      storage_use_azuread: true,
      features: [{
        // Deleted vaults stay recoverable for 7 days; purging needs subscription-level access the deploy identity lacks.
        key_vault: [{ purge_soft_delete_on_destroy: false, recover_soft_deleted_key_vaults: false }],
        resource_group: [{ prevent_deletion_if_contains_resources: true }],
      }],
    }] } },
  };

  // Shared base: logs, the Container Apps environment (consumption only), the runtime identity,
  // the image registry and the secrets vault.
  const base: EngineResourceMapping = { actionId: 'environment:base', kind: 'service', name: 'environment', billable: true };
  const registry: EngineResourceMapping = { actionId: 'registry:images', kind: 'service', name: 'images', billable: true };
  const vault: EngineResourceMapping = { actionId: 'secrets:vault', kind: 'secret', name: 'vault', dataBearing: true };
  const runtime: EngineResourceMapping = { actionId: 'identity:runtime', kind: 'service', name: 'runtime' };
  resources['azurerm_log_analytics_workspace.logs'] = base;
  resources['azurerm_container_app_environment.main'] = base;
  resources['azurerm_user_assigned_identity.runtime'] = runtime;
  resources['azurerm_container_registry.images'] = registry;
  resources['azurerm_role_assignment.runtime_pull'] = runtime;
  resources['azurerm_key_vault.secrets'] = vault;
  resources['azurerm_role_assignment.runtime_secrets'] = runtime;
  files['base.tf.json'] = {
    resource: {
      azurerm_log_analytics_workspace: { logs: { name: `${input.prefix}-logs`, ...placed, sku: 'PerGB2018', retention_in_days: 30,
        // About 4.5 GB a month: inside Log Analytics' 5 GB monthly free allowance.
        daily_quota_gb: 0.15 } },
      // No workload profiles, private endpoint or maintenance window: those bill $0.10/hour per environment.
      azurerm_container_app_environment: { main: { name: `${input.prefix}-apps`, ...placed,
        log_analytics_workspace_id: '${azurerm_log_analytics_workspace.logs.id}', logs_destination: 'log-analytics' } },
      azurerm_user_assigned_identity: { runtime: { name: `${input.prefix}-runtime`, ...placed } },
      azurerm_container_registry: { images: { name: names.registry, ...placed, sku: 'Basic', admin_enabled: false, anonymous_pull_enabled: false } },
      azurerm_key_vault: { secrets: { name: names.vault, ...placed, tenant_id: input.tenantId, sku_name: 'standard', rbac_authorization_enabled: true,
        soft_delete_retention_days: 7, purge_protection_enabled: false } },
      azurerm_role_assignment: {
        runtime_pull: roleAssignment('${azurerm_container_registry.images.id}', ROLE.acrPull, 'Hypervibe: the app pulls its images'),
        runtime_secrets: roleAssignment('${azurerm_key_vault.secrets.id}', ROLE.keyVaultSecretsUser, 'Hypervibe: the app reads its secrets'),
      },
    },
  };

  // Storage: one account, a private container per bucket, no shared keys; the app uses its identity.
  const buckets = input.storage ?? [];
  if (buckets.length) {
    const account: EngineResourceMapping = { actionId: 'storage:account', kind: 'storage', name: 'account', dataBearing: true, billable: true };
    resources['azurerm_storage_account.files'] = account;
    resources['azurerm_role_assignment.runtime_storage'] = runtime;
    const containers: Record<string, unknown> = {};
    for (const bucket of buckets) {
      if (!/^[a-z0-9](?:[a-z0-9]|-(?=[a-z0-9])){2,62}$/.test(bucket.container)) throw new Error(`Storage container name ${bucket.container} is invalid.`);
      const key = azureKey(bucket.name);
      containers[key] = { name: bucket.container, storage_account_id: '${azurerm_storage_account.files.id}', container_access_type: 'private' };
      resources[`azurerm_storage_container.${key}`] = { actionId: `storage:${bucket.name}`, kind: 'storage', name: bucket.name, dataBearing: true, billable: true };
    }
    files['storage.tf.json'] = { resource: {
      azurerm_storage_account: { files: { name: names.storage, ...placed, account_kind: 'StorageV2', account_tier: 'Standard', account_replication_type: 'LRS',
        https_traffic_only_enabled: true, min_tls_version: 'TLS1_2', allow_nested_items_to_be_public: false, shared_access_key_enabled: false,
        default_to_oauth_authentication: true, cross_tenant_replication_enabled: false } },
      azurerm_storage_container: containers,
      azurerm_role_assignment: { runtime_storage: roleAssignment('${azurerm_storage_account.files.id}', ROLE.storageBlobDataContributor, 'Hypervibe: the app reads and writes its files') },
    } };
  }

  // Database: Flexible Server on a public, TLS-only endpoint. The administrator password is
  // generated by an ephemeral resource and sent write-only: nobody, including state, ever holds it.
  // Hypervibe administers the server as the deploy identity (Entra) and creates the app's own login.
  if (input.database) {
    if (!Number.isInteger(input.database.version) || input.database.version < 13 || input.database.version > 18) throw new Error(`PostgreSQL ${input.database.version} is not supported.`);
    const mapping: EngineResourceMapping = { actionId: 'database:postgres', kind: 'database', name: 'postgres', dataBearing: true, billable: true };
    for (const address of ['azurerm_postgresql_flexible_server.postgres', 'azurerm_postgresql_flexible_server_active_directory_administrator.deploy',
      'azurerm_postgresql_flexible_server_database.app', 'azurerm_postgresql_flexible_server_firewall_rule.public']) resources[address] = mapping;
    files['database.tf.json'] = {
      ephemeral: { random_password: { postgres_admin: { length: 40, special: false } } },
      resource: {
        azurerm_postgresql_flexible_server: { postgres: {
          name: names.database, ...placed, version: String(input.database.version),
          sku_name: input.database.skuName ?? 'B_Standard_B1ms', storage_mb: input.database.storageMb ?? 32768, auto_grow_enabled: true,
          backup_retention_days: 7, geo_redundant_backup_enabled: false, public_network_access_enabled: true,
          administrator_login: 'hvadmin', administrator_password_wo: '${ephemeral.random_password.postgres_admin.result}', administrator_password_wo_version: 1,
          authentication: [{ active_directory_auth_enabled: true, password_auth_enabled: true, tenant_id: input.tenantId }],
          // Azure picks the availability zone; it is not drift.
          lifecycle: [{ ignore_changes: ['zone'] }],
        } },
        azurerm_postgresql_flexible_server_active_directory_administrator: { deploy: {
          server_name: '${azurerm_postgresql_flexible_server.postgres.name}', resource_group_name: input.resourceGroup, tenant_id: input.tenantId,
          object_id: input.deployPrincipalId, principal_name: input.deployPrincipalName, principal_type: 'ServicePrincipal',
        } },
        azurerm_postgresql_flexible_server_database: { app: { name: 'app', server_id: '${azurerm_postgresql_flexible_server.postgres.id}', charset: 'UTF8', collation: 'en_US.utf8' } },
        // Container Apps on the consumption plan have no fixed outbound address; TLS (on by default) and
        // generated 32+ character passwords protect the endpoint, as with Aurora on AWS.
        azurerm_postgresql_flexible_server_firewall_rule: { public: { name: 'hypervibe-public-tls', server_id: '${azurerm_postgresql_flexible_server.postgres.id}',
          start_ip_address: '0.0.0.0', end_ip_address: '255.255.255.255' } },
      },
      output: { database_host: { value: '${azurerm_postgresql_flexible_server.postgres.fqdn}' } },
    };
  }

  // Web services: Container Apps that scale to zero, pull with the runtime identity and read
  // secrets as Key Vault references (values never enter configuration or state).
  const services = input.services ?? [];
  const secretNames = (input.secretKeys ?? []).map((key) => ({ key, name: azureSecretName(key) }));
  const seen = new Map<string, string>();
  for (const { key, name } of secretNames) {
    if (seen.has(name)) throw new Error(`Secrets ${seen.get(name)} and ${key} map to the same Key Vault name ${name}.`);
    seen.set(name, key);
  }
  if (services.length) {
    const apps: Record<string, unknown> = {};
    const outputs: Record<string, unknown> = {};
    for (const service of services) {
      if (!/^[a-z][a-z0-9-]{0,30}[a-z0-9]$/.test(service.resourceName) || service.resourceName.includes('--')) throw new Error(`Container App name ${service.resourceName} is invalid.`);
      const key = azureKey(service.logicalName);
      resources[`azurerm_container_app.${key}`] = { actionId: `service:${service.logicalName}`, kind: 'service', name: service.logicalName, billable: true };
      const conflicts = Object.keys(service.env ?? {}).filter((name) => (input.secretKeys ?? []).includes(name));
      if (conflicts.length) throw new Error(`${conflicts.join(', ')} ${conflicts.length === 1 ? 'is' : 'are'} both a secret and a plain variable.`);
      if (service.env && 'AZURE_CLIENT_ID' in service.env) throw new Error('AZURE_CLIENT_ID is set by Hypervibe to the app\'s own identity; remove it from envVars.');
      const probe = service.healthCheckPath ? { path: service.healthCheckPath, port: service.targetPort, transport: 'HTTP' } : undefined;
      apps[key] = {
        name: service.resourceName, resource_group_name: input.resourceGroup, container_app_environment_id: '${azurerm_container_app_environment.main.id}',
        revision_mode: 'Single', tags,
        identity: [{ type: 'UserAssigned', identity_ids: ['${azurerm_user_assigned_identity.runtime.id}'] }],
        registry: [{ server: '${azurerm_container_registry.images.login_server}', identity: '${azurerm_user_assigned_identity.runtime.id}' }],
        secret: secretNames.map(({ name }) => ({ name, key_vault_secret_id: `\${azurerm_key_vault.secrets.vault_uri}secrets/${name}`, identity: '${azurerm_user_assigned_identity.runtime.id}' })),
        ingress: [{ external_enabled: service.public, target_port: service.targetPort, transport: 'auto', allow_insecure_connections: false,
          traffic_weight: [{ latest_revision: true, percentage: 100 }] }],
        template: [{
          min_replicas: 0, max_replicas: service.maxReplicas ?? 2,
          container: [{
            name: 'app', image: service.initialImage, cpu: service.cpu ?? 0.25, memory: `${service.memory ?? 0.5}Gi`,
            env: [
              // Literal values: OpenTofu would otherwise read ${...} and %{...} in them as templates.
              ...Object.entries(service.env ?? {}).sort(([a], [b]) => a.localeCompare(b)).map(([name, value]) => ({ name, value: value.replace(/([$%])\{/g, '$1$1{') })),
              // DefaultAzureCredential picks the runtime identity with this; it is an id, not a secret.
              { name: 'AZURE_CLIENT_ID', value: '${azurerm_user_assigned_identity.runtime.client_id}' },
              ...secretNames.map(({ key, name }) => ({ name: key, secret_name: name })),
            ],
            ...(probe ? { readiness_probe: [probe], startup_probe: [probe] } : {}),
          }],
        }],
        // The pull and secret roles must exist before the first revision starts.
        depends_on: ['azurerm_role_assignment.runtime_pull', 'azurerm_role_assignment.runtime_secrets'],
        // The release path (CI or hv_deploy) owns the image after creation.
        lifecycle: [{ ignore_changes: ['template[0].container[0].image'] }],
      };
      outputs[`service_${key}_url`] = { value: `https://\${azurerm_container_app.${key}.ingress[0].fqdn}` };
    }
    files['services.tf.json'] = { resource: { azurerm_container_app: apps }, output: outputs };
  }

  files['outputs.tf.json'] = { output: {
    registry_login_server: { value: '${azurerm_container_registry.images.login_server}' },
    runtime_identity_client_id: { value: '${azurerm_user_assigned_identity.runtime.client_id}' },
    key_vault_uri: { value: '${azurerm_key_vault.secrets.vault_uri}' },
    ...(buckets.length ? { storage_blob_endpoint: { value: '${azurerm_storage_account.files.primary_blob_endpoint}' } } : {}),
  } };
  return { files, resources };
}
